115→export function MessageBubble({ message, messageIndex }: { message: ChatMessage; messageIndex: number }) {
116→  const { t } = useTranslation();
117→  const { isStreaming, editMessage, deleteMessage } = useAgent();
118→  const [isEditing, setIsEditing] = useState(false);
119→  const [editText, setEditText] = useState(message.content);
120→  const [isConfirmingDelete, setIsConfirmingDelete] = useState(false);
121→  const textareaRef = useRef<HTMLTextAreaElement>(null);
122→
123→  const isUser = message.role === 'user';
124→  const hasSegments = !isUser && message.segments && message.segments.length > 0;
125→
126→  useEffect(() => {
127→    if (isEditing && textareaRef.current) {
128→      textareaRef.current.focus();
129→      textareaRef.current.selectionStart = textareaRef.current.value.length;
130→    }
131→  }, [isEditing]);
132→
133→  const handleEdit = () => {
134→    setEditText(message.content);
135→    setIsEditing(true);
136→    setIsConfirmingDelete(false);
137→  };
138→
139→  const handleCancelEdit = () => {
140→    setIsEditing(false);
141→    setEditText(message.content);
142→  };
143→
144→  const handleSaveEdit = () => {
145→    const trimmed = editText.trim();
146→    if (!trimmed || trimmed === message.content) {
147→      handleCancelEdit();
148→      return;
149→    }
150→    setIsEditing(false);
151→    editMessage(messageIndex, trimmed);
152→  };
153→
154→  const handleDeleteConfirm = () => {
155→    setIsConfirmingDelete(false);
156→    deleteMessage(messageIndex);
157→  };
158→
159→  const handleKeyDown = (e: React.KeyboardEvent) => {
160→    if (e.key === 'Escape') {
161→      handleCancelEdit();
162→    } else if (e.key === 'Enter' && !e.shiftKey && !e.nativeEvent.isComposing) {
163→      e.preventDefault();
164→      handleSaveEdit();
165→    }
166→  };
167→
168→  let streamingRemainder: string | undefined;
169→  if (hasSegments && message.isStreaming && message.content) {
170→    const segmentedText = message.segments!
171→      .filter((s) => s.type === 'thinking' || s.type === 'answer')
172→      .map((s) => s.text || '')
173→      .join('');
174→    const remaining = message.content.slice(segmentedText.length);
175→    if (remaining.trim()) {
176→      streamingRemainder = remaining;
177→    }
178→  }
179→
180→  const hasAnswer = !!hasSegments && message.segments!.some((s) => s.type === 'answer');
181→  const isInAnswerPhase = message.currentPhase === 'answer';
182→  const isThinkingPhase = !!message.isStreaming && !hasAnswer && !isInAnswerPhase;
183→
184→  const hasCharts = hasSegments && message.segments!.some(
185→    (s) => (s.type === 'tool' && s.toolResult?.chart_spec) || (s.type === 'subagent_end' && s.chart_spec)
186→  );
187→
188→  const answerBlockSegments = hasSegments
189→    ? message.segments!
190→        .filter((s) =>
191→          (s.type === 'answer' && s.text?.trim()) ||
192→          (s.type === 'subagent_end' && !s.chart_spec && s.text?.trim() && !hasAnswer) ||
193→          (s.type === 'tool' && s.toolResult?.chart_spec) ||
194→          (s.type === 'subagent_end' && s.chart_spec)
195→        )
196→        .map((s) => {
197→          if ((s.type === 'answer' || (s.type === 'subagent_end' && !s.chart_spec)) && s.text && hasCharts) {
198→            return { ...s, text: stripChartSpecBlocks(s.text) };
199→          }
200→          return s;
201→        })
202→        .filter((s) => {
203→          // Remove text segments that became empty after stripping chart blocks
204→          if ((s.type === 'answer' || (s.type === 'subagent_end' && !s.chart_spec)) && !s.text?.trim()) {
205→            return false;
206→          }
207→          return true;
208→        })
209→    : [];
210→
211→  const questionSegments = hasSegments
212→    ? message.segments!.filter((s) => s.type === 'user_question' && s.questionData)
213→    : [];
214→
215→  return (
216→    <div className={`message-bubble message-bubble--${message.role}`}>
217→      <div className="message-bubble__header">
218→        {isUser ? t('you') : t('assistant')}
219→        {isUser && !isStreaming && !isEditing && !isConfirmingDelete && (
220→          <span className="message-bubble__actions">
221→            <button
222→              className="message-bubble__action-btn"
223→              onClick={handleEdit}
224→              title={t('editMessage')}
225→            >
226→              &#9998;
227→            </button>
228→            <button
229→              className="message-bubble__action-btn message-bubble__action-btn--delete"
230→              onClick={() => setIsConfirmingDelete(true)}
231→              title={t('deleteMessage')}
232→            >
233→              &#128465;
234→            </button>
235→          </span>
236→        )}
237→      </div>
238→
239→      {isUser && isConfirmingDelete && (
240→        <div className="message-bubble__confirm-delete">
241→          <span>{t('deleteConfirm')}</span>
242→          <div className="message-bubble__confirm-actions">
243→            <button
244→              className="message-bubble__confirm-btn message-bubble__confirm-btn--delete"
245→              onClick={handleDeleteConfirm}
246→            >
247→              {t('delete')}
248→            </button>
249→            <button
250→              className="message-bubble__confirm-btn"
251→              onClick={() => setIsConfirmingDelete(false)}
252→            >
253→              {t('cancel')}
254→            </button>
255→          </div>
256→        </div>
257→      )}
258→
259→      {isUser && isEditing ? (
260→        <div className="message-bubble__edit-mode">
261→          <textarea
262→            ref={textareaRef}
263→            className="message-bubble__edit-textarea"
264→            value={editText}
265→            onChange={(e) => setEditText(e.target.value)}
266→            onKeyDown={handleKeyDown}
267→            rows={3}
268→          />
269→          <div className="message-bubble__edit-actions">
270→            <button
271→              className="message-bubble__edit-btn message-bubble__edit-btn--save"
272→              onClick={handleSaveEdit}
273→            >
274→              {t('saveResend')}
275→            </button>
276→            <button
277→              className="message-bubble__edit-btn"
278→              onClick={handleCancelEdit}
279→            >
280→              {t('cancel')}
281→            </button>
282→          </div>
283→        </div>
284→      ) : hasSegments ? (
285→        <div className="message-bubble__segments">
286→          {!questionSegments.some((s) => !s.userAnswer) && (
287→            <ThinkingBlock
288→              segments={message.segments!}
289→              streamingRemainder={isThinkingPhase ? streamingRemainder : undefined}
290→              isThinkingPhase={isThinkingPhase}
291→              isAgentStreaming={!!message.isStreaming}
292→              hasAnswer={hasAnswer}
293→            />
294→          )}
295→          {questionSegments.map((seg, i) => (
296→            <div key={`question-${i}`} className="message-bubble__segment message-bubble__segment--question">
297→              <UserQuestion
298→                questionData={seg.questionData!}
299→                userAnswer={seg.userAnswer}
300→                userFreeText={seg.userFreeText}
301→              />
302→            </div>
303→          ))}
304→          {answerBlockSegments.length > 0 && (
305→            <div className="message-bubble__segment message-bubble__segment--answer">
306→              <div className="message-bubble__segment-label message-bubble__segment-label--answer">{t('answer')}</div>
307→              {answerBlockSegments.map((seg, i) => {
308→                // Chart segment (tool with chart_spec or subagent_end with chart_spec)
309→                if ((seg.type === 'tool' && seg.toolResult?.chart_spec) || (seg.type === 'subagent_end' && seg.chart_spec)) {
310→                  return (
311→                    <div key={`chart-${i}`} className="message-bubble__chart-in-answer">
312→                      {seg.type === 'tool' && seg.toolResult ? (
313→                        <InlineQueryResult result={seg.toolResult!} />
314→                      ) : seg.chart_spec ? (
315→                        <ChartWidget data={seg.chart_spec.data} layout={seg.chart_spec.layout} frames={seg.chart_spec.frames} />
316→                      ) : null}
317→                    </div>
318→                  );
319→                }
320→                // Text segment (answer or subagent_end without chart_spec)
321→                return (
322→                  <div key={`answer-${i}`} className="message-bubble__segment-content">
323→                    <ReactMarkdown remarkPlugins={[remarkGfm]}>{seg.text!}</ReactMarkdown>
324→                  </div>
325→                );
326→              })}
327→              {/* Render streaming remainder inside the same answer block to avoid duplicate headers */}
328→              {isInAnswerPhase && streamingRemainder?.trim() && (() => {
329→                const displayText = hasCharts ? stripChartSpecBlocks(streamingRemainder) : streamingRemainder;
330→                return displayText?.trim() ? (
331→                  <div className="message-bubble__segment-content">
332→                    <ReactMarkdown remarkPlugins={[remarkGfm]}>{displayText}</ReactMarkdown>
333→                  </div>
334→                ) : null;
335→              })()}
336→            </div>
337→          )}
338→          {/* Only show standalone streaming answer block when no answer segments exist yet */}
339→          {answerBlockSegments.length === 0 && isInAnswerPhase && streamingRemainder?.trim() && (() => {
340→            const displayText = hasCharts ? stripChartSpecBlocks(streamingRemainder) : streamingRemainder;
341→            return displayText?.trim() ? (
342→              <div className="message-bubble__segment message-bubble__segment--answer">
343→                <div className="message-bubble__segment-label message-bubble__segment-label--answer">{t('answer')}</div>
344→                <div className="message-bubble__segment-content">
345→                  <ReactMarkdown remarkPlugins={[remarkGfm]}>{displayText}</ReactMarkdown>
346→                </div>
347→              </div>
348→            ) : null;
349→          })()}
350→          {message.isStreaming && !message.content && questionSegments.length === 0 && (
351→            <span className="message-bubble__typing">{t('thinking')}</span>
352→          )}
353→        </div>
354→      ) : (
355→        <>
356→          <div className="message-bubble__content">
357→            {message.content ? (
358→              <ReactMarkdown remarkPlugins={[remarkGfm]}>{message.content}</ReactMarkdown>
359→            ) : message.isStreaming ? (
360→              <span className="message-bubble__typing">{t('thinking')}</span>
361→            ) : null}
362→          </div>
363→          {message.toolCalls && message.toolCalls.length > 0 && (
364→            <div className="message-bubble__tools">
365→              {message.toolCalls.map((tc) => (
366→                <InlineQueryResult key={tc.toolCallId} result={tc} />
367→              ))}
368→            </div>
369→          )}
370→        </>
371→      )}
372→    </div>
373→  );
374→}
