  1→import {
  2→  useCallback,
  3→  useRef,
  4→  useState,
  5→  type ReactNode,
  6→} from 'react';
  7→import { AgentContext } from '../hooks/useAgent';
  8→import { runAgentLoop, runAgentEditLoop } from '../agent/agentService';
  9→import type { ChatMessage, ContentSegment, ToolCallResult } from '../types';
 10→import { useSessionId } from '../hooks/useSessionId';
 11→import { generateUUID } from '../utils/uuid';
 12→
 13→function generateId() {
 14→  return generateUUID();
 15→}
 16→
 17→export function AgentProvider({
 18→  children,
 19→  refreshTables,
 20→}: {
 21→  children: ReactNode;
 22→  refreshTables: () => Promise<void>;
 23→}) {
 24→  const userSessionId = useSessionId();
 25→  const [messages, setMessages] = useState<ChatMessage[]>([]);
 26→  const [isStreaming, setIsStreaming] = useState(false);
 27→  const abortRef = useRef<AbortController | null>(null);
 28→  const textBufferRef = useRef('');
 29→  const flushTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
 30→  const assistantIdRef = useRef('');
 31→  const segmentsRef = useRef<ContentSegment[]>([]);
 32→  const currentTextRef = useRef('');
 33→  const phaseRef = useRef<'thinking' | 'answer'>('thinking');
 34→  const sessionIdRef = useRef<string | null>(null);
 35→  const pendingHistoryRef = useRef<{ role: string; content: string }[] | null>(null);
 36→
 37→  const flushText = useCallback(() => {
 38→    const text = textBufferRef.current;
 39→    if (!text) return;
 40→    const id = assistantIdRef.current;
 41→    currentTextRef.current += text;
 42→    setMessages((prev) =>
 43→      prev.map((m) =>
 44→        m.id === id ? { ...m, content: m.content + text } : m
 45→      )
 46→    );
 47→    textBufferRef.current = '';
 48→  }, []);
 49→
 50→  const sendMessage = useCallback(
 51→    async (text: string) => {
 52→      if (isStreaming) return;
 53→
 54→      const userMsg: ChatMessage = {
 55→        id: generateId(),
 56→        role: 'user',
 57→        content: text,
 58→      };
 59→
 60→      const assistantId = generateId();
 61→      assistantIdRef.current = assistantId;
 62→      const assistantMsg: ChatMessage = {
 63→        id: assistantId,
 64→        role: 'assistant',
 65→        content: '',
 66→        toolCalls: [],
 67→        isStreaming: true,
 68→      };
 69→
 70→      setMessages((prev) => [...prev, userMsg, assistantMsg]);
 71→      setIsStreaming(true);
 72→      textBufferRef.current = '';
 73→      segmentsRef.current = [];
 74→      currentTextRef.current = '';
 75→      phaseRef.current = 'thinking';
 76→
 77→      // If there's pending history from a delete, start a new Langfuse session with that context
 78→      const pendingHistory = pendingHistoryRef.current;
 79→      pendingHistoryRef.current = null;
 80→      const langfuseSessionId = pendingHistory ? generateUUID() : null;
 81→
 82→      const controller = new AbortController();
 83→      abortRef.current = controller;
 84→
 85→      await runAgentLoop(
 86→        text,
 87→        sessionIdRef.current,
 88→        langfuseSessionId,
 89→        pendingHistory,
 90→        {
 91→          onTextChunk: (chunk) => {
 92→            textBufferRef.current += chunk;
 93→            if (!flushTimerRef.current) {
 94→              flushTimerRef.current = setTimeout(() => {
 95→                flushText();
 96→                flushTimerRef.current = null;
 97→              }, 50);
 98→            }
 99→          },
100→          onThinkingDone: () => {
101→            // Extended thinking just ended and a text block is starting.
102→            // Create a thinking segment from accumulated thinking text.
103→            if (flushTimerRef.current) {
104→              clearTimeout(flushTimerRef.current);
105→              flushTimerRef.current = null;
106→            }
107→            flushText();
108→            if (currentTextRef.current.trim()) {
109→              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
110→              currentTextRef.current = '';
111→            }
112→            phaseRef.current = 'answer';
113→            setMessages((prev) =>
114→              prev.map((m) =>
115→                m.id === assistantId
116→                  ? { ...m, currentPhase: 'answer', segments: [...segmentsRef.current] }
117→                  : m
118→              )
119→            );
120→          },
121→          onToolCall: (pending: ToolCallResult) => {
122→            if (flushTimerRef.current) {
123→              clearTimeout(flushTimerRef.current);
124→              flushTimerRef.current = null;
125→            }
126→            flushText();
127→            if (currentTextRef.current.trim()) {
128→              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
129→              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
130→              currentTextRef.current = '';
131→            }
132→            // Add a pending tool segment so the input is shown immediately
133→            segmentsRef.current.push({
134→              type: 'tool',
135→              toolResult: pending,
136→            });
137→            setMessages((prev) =>
138→              prev.map((m) =>
139→                m.id === assistantId
140→                  ? { ...m, currentPhase: 'answer', segments: [...segmentsRef.current] }
141→                  : m
142→              )
143→            );
144→          },
145→          onToolResult: (result: ToolCallResult) => {
146→            // Merge result into pending tool segment (keep input info, add output)
147→            const pendingIdx = segmentsRef.current.findIndex(
148→              (s) => s.type === 'tool' && s.toolResult?.toolCallId === result.toolCallId
149→            );
150→            if (pendingIdx !== -1) {
151→              const pending = segmentsRef.current[pendingIdx].toolResult!;
152→              segmentsRef.current[pendingIdx] = {
153→                type: 'tool',
154→                toolResult: {
155→                  ...pending,
156→                  ...result,
157→                  sql: result.sql || pending.sql,
158→                  toolName: result.toolName || pending.toolName,
159→                  command: result.command || pending.command,
160→                  toolInput: result.toolInput || pending.toolInput,
161→                },
162→              };
163→            } else {
