import type { ToolCallResult, UserQuestionData, UserQuestionOption } from '../types';

interface AgentCallbacks {
  onTextChunk: (text: string) => void;
  onThinkingDone: () => void;
  onToolCall: (pending: ToolCallResult) => void;
  onToolResult: (result: ToolCallResult) => void;
  onSubagentStart?: (data: { id: string; name: string; prompt: string }) => void;
  onSubagentEnd?: (data: { id: string; name: string; result?: string; chart_spec?: { data: unknown[]; layout?: Record<string, unknown> } }) => void;
  onDone: (sessionId: string | null) => void;
  onError: (error: string) => void;
  onUserQuestion?: (data: UserQuestionData) => void;
}

export type { AgentCallbacks };

async function streamSSE(
  response: Response,
  callbacks: AgentCallbacks,
  signal?: AbortSignal,
): Promise<void> {
  const reader = response.body?.getReader();
  if (!reader) {
    callbacks.onError('No response stream');
    return;
  }

  let doneReceived = false;
  const wrappedCallbacks: AgentCallbacks = {
    ...callbacks,
    onDone: (sessionId) => {
      doneReceived = true;
      callbacks.onDone(sessionId);
    },
    onError: (error) => {
      doneReceived = true;
      callbacks.onError(error);
    },
  };

  try {
    const decoder = new TextDecoder();
    let buffer = '';
    let eventType = '';

    while (true) {
      const { done, value } = await reader.read();
      if (done) break;

      buffer += decoder.decode(value, { stream: true });
      const lines = buffer.split('\n');
      buffer = lines.pop() ?? '';
      for (const line of lines) {
        if (line.startsWith('event: ')) {
          eventType = line.slice(7).trim();
        } else if (line.startsWith('data: ')) {
          const data = line.slice(6);
          try {
            const parsed = JSON.parse(data);
            handleSSEEvent(eventType, parsed, wrappedCallbacks);
          } catch {
            // Skip malformed JSON
          }
          eventType = '';
        }
      }
    }

    // Process any remaining data left in buffer after stream ends
    if (buffer.trim()) {
      const remainingLines = buffer.split('\n');
      for (const line of remainingLines) {
        if (line.startsWith('event: ')) {
          eventType = line.slice(7).trim();
        } else if (line.startsWith('data: ')) {
          const data = line.slice(6);
          try {
            const parsed = JSON.parse(data);
            handleSSEEvent(eventType, parsed, wrappedCallbacks);
          } catch {
            // Skip malformed JSON
          }
          eventType = '';
        }
      }
    }

    // Safety net: if stream ended without done/error, force done
    if (!doneReceived) {
      callbacks.onDone(null);
    }
  } catch (e: unknown) {
    if (signal?.aborted) return;
    const msg = e instanceof Error ? e.message : 'Connection failed';
    callbacks.onError(msg);
  }
}

export async function runAgentLoop(
  message: string,
  agentSessionId: string | null,
  langfuseSessionId: string | null,
  conversationHistory: { role: string; content: string }[] | null,
  callbacks: AgentCallbacks,
  signal?: AbortSignal,
  userSessionId?: string,
): Promise<void> {
  try {
    const response = await fetch('/api/chat', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        ...(userSessionId ? { 'X-Session-ID': userSessionId } : {}),
      },
      body: JSON.stringify({
        message,
        session_id: agentSessionId,
        langfuse_session_id: langfuseSessionId,
        conversation_history: conversationHistory ?? [],
      }),
      signal,
    });

    if (!response.ok) {
      const errorText = await response.text();
      callbacks.onError(`Server error: ${errorText}`);
      return;
    }

    await streamSSE(response, callbacks, signal);
  } catch (e: unknown) {
    if (signal?.aborted) return;
    const msg = e instanceof Error ? e.message : 'Connection failed';
    callbacks.onError(msg);
  }
}

export async function runAgentEditLoop(
  newMessage: string,
  conversationHistory: { role: string; content: string }[],
  langfuseSessionId: string | null,
  callbacks: AgentCallbacks,
  signal?: AbortSignal,
  userSessionId?: string,
): Promise<void> {
  try {
    const response = await fetch('/api/chat/edit', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        ...(userSessionId ? { 'X-Session-ID': userSessionId } : {}),
      },
      body: JSON.stringify({
        new_message: newMessage,
        conversation_history: conversationHistory,
        langfuse_session_id: langfuseSessionId,
      }),
      signal,
    });

    if (!response.ok) {
      const errorText = await response.text();
      callbacks.onError(`Server error: ${errorText}`);
      return;
    }

    await streamSSE(response, callbacks, signal);
  } catch (e: unknown) {
    if (signal?.aborted) return;
    const msg = e instanceof Error ? e.message : 'Connection failed';
    callbacks.onError(msg);
  }
}

function handleSSEEvent(
  eventType: string,
  data: Record<string, unknown>,
  callbacks: AgentCallbacks,
) {
  switch (eventType) {
    case 'thinking':
    case 'answer':
      callbacks.onTextChunk(data.text as string);
      break;
    case 'thinking_done':
      callbacks.onThinkingDone();
      break;
    case 'tool_call':
      callbacks.onToolCall({
        toolCallId: (data.id as string) ?? '',
        toolName: (data.name as string) ?? undefined,
        sql: (data.sql as string) ?? '',
        command: (data.command as string) ?? undefined,
        toolInput: (data.input as Record<string, unknown>) ?? undefined,
        columns: [],
        rows: [],
        rowCount: 0,
      });
      break;
    case 'tool_result': {
      const result: ToolCallResult = {
        toolCallId: (data.id as string) ?? '',
        toolName: (data.name as string) ?? undefined,
        sql: (data.sql as string) ?? '',
        columns: (data.columns as string[]) ?? [],
        rows: (data.rows as Record<string, unknown>[]) ?? [],
        rowCount: (data.rowCount as number) ?? 0,
        error: (data.error as string) ?? undefined,
        output: (data.output as string) ?? undefined,
        rawContent: (data.content as string) ?? undefined,
        chart_spec: (data.chart_spec as { data: unknown[]; layout?: Record<string, unknown> }) ?? undefined,
      };
      callbacks.onToolResult(result);
      break;
    }
    case 'subagent_start':
      callbacks.onSubagentStart?.({
        id: data.id as string,
        name: data.name as string,
        prompt: (data.prompt as string) ?? '',
      });
      break;
    case 'subagent_end':
      callbacks.onSubagentEnd?.({
        id: data.id as string,
        name: data.name as string,
        result: (data.result as string) ?? undefined,
        chart_spec: (data.chart_spec as { data: unknown[]; layout?: Record<string, unknown> }) ?? undefined,
      });
      break;
    case 'user_question': {
      // Normalize options: the agent may send plain strings or {label, description} objects
      const rawOptions = (data.options as unknown[]) ?? [];
      const normalizedOptions: UserQuestionOption[] = (Array.isArray(rawOptions) ? rawOptions : []).map(
        (opt: unknown) => {
          if (typeof opt === 'string') return { label: opt };
          if (typeof opt === 'object' && opt !== null && 'label' in opt) return opt as UserQuestionOption;
          return { label: String(opt) };
        }
      );
      callbacks.onUserQuestion?.({
        questionId: data.question_id as string,
        question: data.question as string,
        options: normalizedOptions,
        multiSelect: (data.multi_select as boolean) ?? false,
      });
      break;
    }
    case 'done':
      callbacks.onDone((data.session_id as string) ?? null);
      break;
    case 'error':
      callbacks.onError((data.message as string) ?? 'Unknown error');
      break;
  }
}

import json
import logging
import anyio
from starlette.applications import Starlette
from starlette.requests import Request
from starlette.responses import Response
from starlette.routing import Route, Mount
from mcp.server.sse import SseServerTransport
from mcp.server.lowlevel.server import Server as MCPServer
import mcp.types as types
from app.session_manager import session_manager
from app.database import Database
from app.pending_questions import pending_question_store

logger = logging.getLogger(__name__)

MAX_RESULT_ROWS = 100

# The path here is relative to the Starlette app mount point (/mcp), not the
# full URL.  Starlette sets root_path=/mcp in the ASGI scope, and the MCP SDK
# prepends root_path when advertising the endpoint URL to clients.  Using
# "/messages/" avoids a double-prefix (/mcp/mcp/messages/).
sse_transport = SseServerTransport("/messages/")


def _create_mcp_server(db: Database, session_id: str) -> MCPServer:
    """Create a duckdb-data-agent MCP server with execute_sql, ask_user_question, and render_chart tools bound to a DuckDB instance."""
    server = MCPServer("duckdb-data-agent")

    @server.list_tools()
    async def list_tools() -> list[types.Tool]:
        return [
            types.Tool(
                name="execute_sql",
                description=(
                    "Execute a SQL query against the DuckDB database. "
                    "Results are returned as JSON with columns, rows, and rowCount."
                ),
                inputSchema={
                    "type": "object",
                    "properties": {"sql": {"type": "string"}},
                    "required": ["sql"],
                },
            ),
            types.Tool(
                name="ask_user_question",
                description=(
                    "Ask the user a clarifying question with selectable options. "
                    "Pauses until the user responds."
                ),
                inputSchema={
                    "type": "object",
                    "properties": {
                        "question": {"type": "string"},
                        "options": {
                            "type": "array",
                            "items": {
                                "type": "object",
                                "properties": {
                                    "label": {"type": "string"},
                                    "description": {"type": "string"},
                                },
                                "required": ["label"],
                            },
                        },
                        "multi_select": {"type": "boolean", "default": False},
                    },
                    "required": ["question", "options"],
                },
            ),
            types.Tool(
                name="render_chart",
                description=(
                    "Render a Plotly chart. Call this as the final step after querying data. "
                    "Pass all Plotly traces in `data` and a layout object with a descriptive `title`."
                ),
                inputSchema={
                    "type": "object",
                    "properties": {
                        "data": {
                            "type": "array",
                            "description": "Array of Plotly trace objects (bar, line, scatter, pie, etc.)",
                            "items": {"type": "object"},
                        },
                        "layout": {
                            "type": "object",
                            "description": "Plotly layout object",
                            "properties": {
                                "title": {"type": "string"},
                            },
                            "required": ["title"],
                        },
                    },
                    "required": ["data", "layout"],
                },
            ),
        ]

    @server.call_tool()
    async def call_tool(
        name: str, arguments: dict
    ) -> list[types.TextContent]:
        if name == "execute_sql":
            sql = arguments.get("sql", "")
            try:
                result = await db.execute_query_async(sql)
                truncated_rows = result["rows"][:MAX_RESULT_ROWS]
                result_json = {
                    "status": "success",
                    "columns": result["columns"],
                    "rows": truncated_rows,
                    "rowCount": result["rowCount"],
                }
                return [types.TextContent(type="text", text=json.dumps(result_json, default=str))]
            except Exception as e:
                error_json = {"status": "error", "error": str(e)}
                return [types.TextContent(type="text", text=json.dumps(error_json))]
        elif name == "ask_user_question":
            question_data = {
                "question": arguments.get("question", ""),
                "options": arguments.get("options", []),
                "multi_select": arguments.get("multi_select", False),
            }
            question_id = pending_question_store.create(session_id, question_data)
            answer = await pending_question_store.wait(session_id, question_id, timeout=300.0)
            if answer is None:
                result = {"timeout": True, "message": "User did not respond within the time limit."}
            else:
                result = answer
            return [types.TextContent(type="text", text=json.dumps(result))]
        elif name == "render_chart":
            data = arguments.get("data")
            layout = arguments.get("layout", {})
            if not isinstance(data, list) or not layout.get("title"):
                logger.warning("render_chart called with missing data or layout.title: %s", arguments)
                return [types.TextContent(type="text", text=json.dumps({"status": "error", "error": "data and layout.title are required"}))]
            # Return a minimal acknowledgement. The chart spec (data + layout) is captured
            # upstream from the tool_use input block in the backend stream handler — not from
            # this response — so we don't need to echo the payload here.
            return [types.TextContent(type="text", text=json.dumps({"status": "rendered"}))]
        else:
            raise ValueError(f"Unknown tool: {name}")

    return server


async def handle_sse(request: Request) -> Response:
    """Handle SSE connection. Requires session_id query param."""
    session_id = request.query_params.get("session_id")
    if not session_id:
        return Response("session_id query parameter is required", status_code=400)

    db = session_manager.get_or_create(session_id)
    server = _create_mcp_server(db, session_id)

    try:
        async with sse_transport.connect_sse(
            request.scope, request.receive, request._send
        ) as streams:
            await server.run(
                streams[0],
                streams[1],
                server.create_initialization_options(),
            )
    except anyio.ClosedResourceError:
        logger.debug("MCP SSE client disconnected (session %s)", session_id)
    except BaseExceptionGroup as eg:
        # The MCP library uses anyio task groups which wrap errors in
        # ExceptionGroups.  Filter out ClosedResourceError (normal client
        # disconnect) and re-raise anything else.
        _, rest = eg.split(anyio.ClosedResourceError)
        if rest:
            raise rest from None
        logger.debug("MCP SSE client disconnected (session %s)", session_id)

    return Response()


mcp_app = Starlette(
    routes=[
        Route("/sse", endpoint=handle_sse, methods=["GET"]),
        Mount("/messages/", app=sse_transport.handle_post_message),
    ]
)

"""Tests for render_chart tool_use capture in stream_chat message handling."""
from app.agent import _build_chart_spec_from_stream_messages


def _make_assistant_msg(parent_tool_use_id, tool_use_name, tool_input):
    """Helper: build a minimal SDK 'assistant' message dict."""
    return {
        "type": "assistant",
        "parent_tool_use_id": parent_tool_use_id,
        "message": {
            "content": [
                {
                    "type": "tool_use",
                    "id": "tu_render_1",
                    "name": tool_use_name,
                    "input": tool_input,
                }
            ]
        },
    }


def test_captures_render_chart_input_as_chart_spec():
    """render_chart tool_use.input is captured as chart_spec for the parent task id."""
    chart_input = {
        "data": [{"type": "bar", "x": ["A", "B"], "y": [1, 2]}],
        "layout": {"title": "Sales by Category"},
    }
    msg = _make_assistant_msg(
        parent_tool_use_id="task_001",
        tool_use_name="mcp__duckdb-data-agent__render_chart",
        tool_input=chart_input,
    )

    specs: dict = {}
    tool_names = {"task_001": "chart-builder"}
    _build_chart_spec_from_stream_messages(msg, tool_names, specs)

    assert specs["task_001"] == chart_input


def test_ignores_non_render_chart_tool_use():
    """Other tool_use blocks in a chart-builder turn are not captured as chart_spec."""
    msg = _make_assistant_msg(
        parent_tool_use_id="task_001",
        tool_use_name="mcp__duckdb-data-agent__execute_sql",
        tool_input={"sql": "SELECT 1"},
    )

    specs: dict = {}
    tool_names = {"task_001": "chart-builder"}
    _build_chart_spec_from_stream_messages(msg, tool_names, specs)

    assert specs == {}


def test_ignores_messages_not_from_chart_builder():
    """Tool_use blocks from non-chart-builder subagents are ignored."""
    msg = _make_assistant_msg(
        parent_tool_use_id="task_002",
        tool_use_name="mcp__duckdb-data-agent__render_chart",
        tool_input={"data": [], "layout": {"title": "x"}},
    )

    specs: dict = {}
    tool_names = {"task_002": "sql-analyst"}  # not chart-builder
    _build_chart_spec_from_stream_messages(msg, tool_names, specs)

    assert specs == {}

